interface StoredUser {
  fullName?: string;
  role?: string;
  package?: string;
}

const SIDEBAR_KEY = 'sidebar-collapsed-preference';

const NavInner: React.FC = () => {
  const location = useLocation();

  const [user, setUser] = useState<StoredUser | null>(() => {
    try { return JSON.parse(localStorage.getItem('auth_user') || 'null'); }
    catch { return null; }
  });

  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(() => {
    if (typeof window === 'undefined') return false;
    const w = window.innerWidth;
    if (w <= 680) return false;
    if (w <= 1024) return true;
    return localStorage.getItem(SIDEBAR_KEY) === 'collapsed';
  });

  const [isMobile, setIsMobile] = useState(() =>
    typeof window !== 'undefined' && window.innerWidth <= 680,
  );
  const [isSmallDesktop, setIsSmallDesktop] = useState(() =>
    typeof window !== 'undefined' && window.innerWidth > 680 && window.innerWidth <= 1024,
  );
  const [isMobileSidebarOpen, setIsMobileSidebarOpen] = useState(false);

  // Allow other MFEs to open the mobile sidebar via CustomEvent
  useEffect(() => {
    const handler = () => setIsMobileSidebarOpen(prev => !prev);
    window.addEventListener('linm:nav:toggle-mobile', handler);
    return () => window.removeEventListener('linm:nav:toggle-mobile', handler);
  }, []);

  // Sync user from localStorage across tabs (login / logout in another tab)
  useEffect(() => {
    const onStorage = (e: StorageEvent) => {
      if (e.key !== 'auth_user') return;
      try { setUser(e.newValue ? JSON.parse(e.newValue) : null); }
      catch { setUser(null); }
    };
    window.addEventListener('storage', onStorage);
    return () => window.removeEventListener('storage', onStorage);
  }, []);

  // Publish sidebar width as a CSS custom property so each MFE's AppLayout
  // can adjust its left margin without needing cross-MFE state.
  useEffect(() => {
    document.documentElement.style.setProperty(
      '--sidebar-width',
      location.pathname === '/login' ? '0px' : isSidebarCollapsed ? '64px' : '280px',
    );
  }, [isSidebarCollapsed, location.pathname]);

  useEffect(() => {
    const handleResize = () => {
      const w = window.innerWidth;
      const mobile = w <= 680;
      const small = w > 680 && w <= 1024;
      setIsMobile(mobile);
      setIsSmallDesktop(small);
      if (small && !isSidebarCollapsed) setIsSidebarCollapsed(true);
      else if (w > 1024) setIsSidebarCollapsed(localStorage.getItem(SIDEBAR_KEY) === 'collapsed');
      else if (mobile) setIsSidebarCollapsed(false);
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [isSidebarCollapsed]);

  const handleToggleSidebar = useCallback(() => {
    setIsSidebarCollapsed(prev => {
      const next = !prev;
      if (!isMobile) localStorage.setItem(SIDEBAR_KEY, next ? 'collapsed' : 'expanded');
      return next;
    });
  }, [isMobile]);

  const handleNavigate = useCallback((path: string) => {
    navigateToUrl(path);
    if (isMobile) setIsMobileSidebarOpen(false);
  }, [isMobile]);

  const handleLogout = useCallback(() => {
    localStorage.removeItem('auth_token');
    localStorage.removeItem('auth_refresh_token');
    localStorage.removeItem('auth_user');
    navigateToUrl('/login');
  }, []);

  const pathname = location.pathname;
  const isEduEnglish     = pathname.startsWith('/edu/english');
  const isEduInteractive = pathname.startsWith('/edu/interactive');
  const activeApp        = getActiveApp(pathname);

  const sections: NavSection[] = isEduEnglish
    ? EDU_ENGLISH_SECTIONS
    : isEduInteractive
      ? EDU_INTERACTIVE_SECTIONS
      : activeApp === 'medical-incidents'
        ? buildMedicalIncidentSections(user?.role as UserRole)
        : buildTaskManagementSections(user?.role as UserRole, 0, 0, user?.package, 0);

  const logoIcon  = isEduEnglish     ? 'fas fa-language'
                  : isEduInteractive ? 'fas fa-chalkboard-teacher'
                  : 'fas fa-hospital-user';

  const logoLabel = isEduEnglish     ? 'Linm Edu — English'
                  : isEduInteractive ? 'Linm Edu — Interactive'
                  : 'QLCV & SC Y Khoa';

  const fullName = user?.fullName || 'Người dùng';
  const parts = fullName.trim().split(' ');
  const userInitials =
    parts.length >= 2
      ? (parts[parts.length - 2].charAt(0) + parts[parts.length - 1].charAt(0)).toUpperCase()
      : fullName.charAt(0).toUpperCase();

  const roleLabel =
    user?.role === 'admin' ? 'Quản trị viên'
    : user?.role === 'manager' ? 'Quản lý'
    : user?.role === 'staff' ? 'Nhân viên'
    : 'Người dùng';

  if (pathname === '/login') return null;

  return (
    <Sidebar
      sections={sections}
      activePath={pathname}
      userName={fullName}
      userRole={roleLabel}
      userInitials={userInitials}
      onNavigate={handleNavigate}
      onLogout={handleLogout}
      isCollapsed={isSidebarCollapsed}
      onToggleCollapse={handleToggleSidebar}
      isMobile={isMobile}
      isSmallDesktop={isSmallDesktop}
      isOpen={isMobileSidebarOpen}
      logoIcon={logoIcon}
      logoLabel={logoLabel}
    />
  );
};

const NavRoot: React.FC = () => (
  <Router>
    <NavInner />
  </Router>
);

export default NavRoot;
